/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Options = new() &OptionsDesc = new() &OptionIndexes = new() LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState' Do Case Case &DDOName.ToUpper() = !'DDO_LOCDESCRICAO' Do 'LoadlocDescricaoOptions' Case &DDOName.ToUpper() = !'DDO_AREENSNOME' Do 'LoadAreEnsNomeOptions' Case &DDOName.ToUpper() = !'DDO_AREENSETAPANOME' Do 'LoadAreEnsEtapaNomeOptions' Case &DDOName.ToUpper() = !'DDO_CARGRUCODIGO' Do 'LoadcarGruCodigoOptions' EndCase
&OptionsJson = &Options.ToJson() &OptionsDescJson = &OptionsDesc.ToJson() &OptionIndexesJson = &OptionIndexes.ToJson()
