Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"AtendimentoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"AtendimentoWWGridState")) Else &GridState.FromXml(&Session.Get(!"AtendimentoWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFATENDIMENTOCODIGO" &TFAtendimentoCodigo.FromString(&GridStateFilterValue.Value) &TFAtendimentoCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFLOCDESCRICAO" &TFlocDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLOCDESCRICAO_SEL" &TFlocDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSNOME" &TFAreEnsNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSNOME_SEL" &TFAreEnsNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSETAPANOME" &TFAreEnsEtapaNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSETAPANOME_SEL" &TFAreEnsEtapaNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFATENDIMENTOTURNO_SEL" &TFAtendimentoTurno_SelsJson = &GridStateFilterValue.Value &TFAtendimentoTurno_Sels.FromJson(&TFAtendimentoTurno_SelsJson) Case &GridStateFilterValue.Name = !"TFCARGRUCODIGO" &TFcarGruCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARGRUCODIGO_SEL" &TFcarGruCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFATENDIMENTOFUNCIONARIOSSEGUNDA" &TFAtendimentoFuncionariosSegunda.FromString(&GridStateFilterValue.Value) &TFAtendimentoFuncionariosSegunda_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFATENDIMENTONORMALSEGUNDA" &TFAtendimentoNormalSegunda.FromString(&GridStateFilterValue.Value) &TFAtendimentoNormalSegunda_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFATENDIMENTOCOLESTEROLSEGUNDA" &TFAtendimentoColesterolSegunda.FromString(&GridStateFilterValue.Value) &TFAtendimentoColesterolSegunda_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFATENDIMENTODIABETICOSEGUNDA" &TFAtendimentoDiabeticoSegunda.FromString(&GridStateFilterValue.Value) &TFAtendimentoDiabeticoSegunda_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFATENDIMENTOGLUTENSEGUNDA" &TFAtendimentoGlutenSegunda.FromString(&GridStateFilterValue.Value) &TFAtendimentoGlutenSegunda_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFATENDIMENTOLACTOSESEGUNDA" &TFAtendimentoLactoseSegunda.FromString(&GridStateFilterValue.Value) &TFAtendimentoLactoseSegunda_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFATENDIMENTOSTATUS_SEL" &TFAtendimentoStatus_SelsJson = &GridStateFilterValue.Value &TFAtendimentoStatus_Sels.FromJson(&TFAtendimentoStatus_SelsJson) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'LOCDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &locDescricao1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'AREENSNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AreEnsNome1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'CARGRUDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carGruDescricao1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'AREENSETAPANOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AreEnsEtapaNome1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'CARGRUQTDEITENS' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carGruQtdeItens1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'LOCDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &locDescricao2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'AREENSNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AreEnsNome2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'CARGRUDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carGruDescricao2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'AREENSETAPANOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AreEnsEtapaNome2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'CARGRUQTDEITENS' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carGruQtdeItens2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'LOCDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &locDescricao3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'AREENSNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AreEnsNome3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'CARGRUDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carGruDescricao3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'AREENSETAPANOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AreEnsEtapaNome3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'CARGRUQTDEITENS' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carGruQtdeItens3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadlocDescricaoOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFlocDescricao = &SearchTxt &TFlocDescricao_Sel.SetEmpty() For Each Atendimento Order prefCodigo, locCodigo using AtendimentoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &locDescricao1, &AreEnsNome1, &carGruDescricao1, &AreEnsEtapaNome1 , &carGruQtdeItens1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &locDescricao2, &AreEnsNome2 , &carGruDescricao2, &AreEnsEtapaNome2, &carGruQtdeItens2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &locDescricao3, &AreEnsNome3, &carGruDescricao3, &AreEnsEtapaNome3, &carGruQtdeItens3, &TFAtendimentoCodigo , &TFAtendimentoCodigo_To, &TFlocDescricao, &TFlocDescricao_Sel, &TFAreEnsNome, &TFAreEnsNome_Sel, &TFAreEnsEtapaNome , &TFAreEnsEtapaNome_Sel, &TFAtendimentoTurno_Sels, &TFcarGruCodigo, &TFcarGruCodigo_Sel, &TFAtendimentoFuncionariosSegunda, &TFAtendimentoFuncionariosSegunda_To , &TFAtendimentoNormalSegunda, &TFAtendimentoNormalSegunda_To, &TFAtendimentoColesterolSegunda, &TFAtendimentoColesterolSegunda_To, &TFAtendimentoDiabeticoSegunda, &TFAtendimentoDiabeticoSegunda_To , &TFAtendimentoGlutenSegunda, &TFAtendimentoGlutenSegunda_To, &TFAtendimentoLactoseSegunda, &TFAtendimentoLactoseSegunda_To, &TFAtendimentoStatus_Sels) Where prefCodigo = &prefCodigo
&count = 0 For Each Atendimento Order prefCodigo, locCodigo &count += 1 EndFor If not locDescricao.IsEmpty() &Option = locDescricao
&InsertIndex = 1 Do while &InsertIndex <= &Options.Count AND &Options.Item(&InsertIndex) < &Option &InsertIndex = &InsertIndex + 1 EndDo &Options.Add(&Option, &InsertIndex) &OptionIndexes.Add(trim(&count.ToFormattedString()), &InsertIndex) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadAreEnsNomeOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFAreEnsNome = &SearchTxt &TFAreEnsNome_Sel.SetEmpty() For Each Atendimento Order prefCodigo, AreEnsCodigo using AtendimentoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &locDescricao1, &AreEnsNome1, &carGruDescricao1, &AreEnsEtapaNome1 , &carGruQtdeItens1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &locDescricao2, &AreEnsNome2 , &carGruDescricao2, &AreEnsEtapaNome2, &carGruQtdeItens2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &locDescricao3, &AreEnsNome3, &carGruDescricao3, &AreEnsEtapaNome3, &carGruQtdeItens3, &TFAtendimentoCodigo , &TFAtendimentoCodigo_To, &TFlocDescricao, &TFlocDescricao_Sel, &TFAreEnsNome, &TFAreEnsNome_Sel, &TFAreEnsEtapaNome , &TFAreEnsEtapaNome_Sel, &TFAtendimentoTurno_Sels, &TFcarGruCodigo, &TFcarGruCodigo_Sel, &TFAtendimentoFuncionariosSegunda, &TFAtendimentoFuncionariosSegunda_To , &TFAtendimentoNormalSegunda, &TFAtendimentoNormalSegunda_To, &TFAtendimentoColesterolSegunda, &TFAtendimentoColesterolSegunda_To, &TFAtendimentoDiabeticoSegunda, &TFAtendimentoDiabeticoSegunda_To , &TFAtendimentoGlutenSegunda, &TFAtendimentoGlutenSegunda_To, &TFAtendimentoLactoseSegunda, &TFAtendimentoLactoseSegunda_To, &TFAtendimentoStatus_Sels) Where prefCodigo = &prefCodigo
&count = 0 For Each Atendimento Order prefCodigo, AreEnsCodigo &count += 1 EndFor If not AreEnsNome.IsEmpty() &Option = AreEnsNome
&InsertIndex = 1 Do while &InsertIndex <= &Options.Count AND &Options.Item(&InsertIndex) < &Option &InsertIndex = &InsertIndex + 1 EndDo &Options.Add(&Option, &InsertIndex) &OptionIndexes.Add(trim(&count.ToFormattedString()), &InsertIndex) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
