&TFcarGruCodigo = &SearchTxt &TFcarGruCodigo_Sel.SetEmpty() For Each Atendimento Order prefCodigo, carGruCodigo using AtendimentoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &locDescricao1, &AreEnsNome1, &carGruDescricao1, &AreEnsEtapaNome1 , &carGruQtdeItens1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &locDescricao2, &AreEnsNome2 , &carGruDescricao2, &AreEnsEtapaNome2, &carGruQtdeItens2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &locDescricao3, &AreEnsNome3, &carGruDescricao3, &AreEnsEtapaNome3, &carGruQtdeItens3, &TFAtendimentoCodigo , &TFAtendimentoCodigo_To, &TFlocDescricao, &TFlocDescricao_Sel, &TFAreEnsNome, &TFAreEnsNome_Sel, &TFAreEnsEtapaNome , &TFAreEnsEtapaNome_Sel, &TFAtendimentoTurno_Sels, &TFcarGruCodigo, &TFcarGruCodigo_Sel, &TFAtendimentoFuncionariosSegunda, &TFAtendimentoFuncionariosSegunda_To , &TFAtendimentoNormalSegunda, &TFAtendimentoNormalSegunda_To, &TFAtendimentoColesterolSegunda, &TFAtendimentoColesterolSegunda_To, &TFAtendimentoDiabeticoSegunda, &TFAtendimentoDiabeticoSegunda_To , &TFAtendimentoGlutenSegunda, &TFAtendimentoGlutenSegunda_To, &TFAtendimentoLactoseSegunda, &TFAtendimentoLactoseSegunda_To, &TFAtendimentoStatus_Sels) Where prefCodigo = &prefCodigo
&count = 0 For Each Atendimento Order prefCodigo, carGruCodigo &count += 1 EndFor If not carGruDescricao.IsEmpty() &Option = carGruCodigo.ToString() &OptionDesc = carGruDescricao
&InsertIndex = 1 Do while &InsertIndex <= &Options.Count AND &OptionsDesc.Item(&InsertIndex) < &OptionDesc &InsertIndex = &InsertIndex + 1 EndDo &Options.Add(&Option, &InsertIndex) &OptionsDesc.Add(&OptionDesc, &InsertIndex) &OptionIndexes.Add(trim(&count.ToFormattedString()), &InsertIndex) EndIf If &Options.Count = 50 Exit EndIf EndFor
